{"pluginId":"order-summary-message","files":[{"relativePath":"manifest.json","content":"{
  "id": "order-summary-message",
  "name": "Order Summary Message",
  "description": "Renders order summaries carried by AG-UI CUSTOM events as an order card inside chat messages.",
  "version": "0.0.1",
  "data": {
    "messageUI": true
  },
