119: function formatMoney(
120:   amount: number | undefined,
121:   currency: string | undefined,
122:   locale: string,
123: ): string | undefined {
124:   if (amount === undefined) return undefined;
125:   const code =
126:     currency !== undefined && /^[A-Za-z]{3}$/.test(currency)
127:       ? currency.toUpperCase()
128:       : undefined;
129:   if (code !== undefined) {
130:     try {
131:       return new Intl.NumberFormat(locale, {
132:         style: "currency",
133:         currency: code,
134:       }).format(amount);
135:     } catch {
136:       // Unknown currency code for Intl: fall back to a plain formatted number.
137:     }
138:   }
139:   const value = new Intl.NumberFormat(locale, {
140:     maximumFractionDigits: 2,
141:   }).format(amount);
142:   return code === undefined ? value : `${value} ${code}`;
143: }
